cd /home/ubuntu/testlogon
TS=$(date +%s)
echo PROD_ERP_FOLD_$TS
echo  | base64 -d > app/routers/erp_gl.py
chown ubuntu:ubuntu app/routers/erp_gl.py
echo  | base64 -d > app/routers/erp_ar.py
chown ubuntu:ubuntu app/routers/erp_ar.py
echo  | base64 -d > app/routers/erp_pricing.py
chown ubuntu:ubuntu app/routers/erp_pricing.py
cp app/main.py app/main.py.bak_erp_$TS
echo  | base64 -d > /home/ubuntu/close_patch_main_erp.py
python3 /home/ubuntu/close_patch_main_erp.py
chown ubuntu:ubuntu app/main.py
echo === ROUTER_MD5 ===
md5sum app/routers/erp_gl.py app/routers/erp_ar.py app/routers/erp_pricing.py
echo === IMPORT_SANITY ===
sudo -u ubuntu bash -lc 'cd /home/ubuntu/testlogon; set -a; . .env.local 2>/dev/null; set +a; .venv/bin/python -c "import app.main; print(chr(73)+chr(77)+chr(80)+chr(79)+chr(82)+chr(84)+chr(95)+chr(79)+chr(75))"' 2>&1 | tail -3
echo === RESTART ===
pkill -f 'uvicorn app.main' || true
sleep 3
sudo -u ubuntu bash /home/ubuntu/restart_backend.sh || true
sleep 6
for i in $(seq 1 30); do c=$(curl -s -o /dev/null -w '%{http_code}' http://localhost:8000/openapi.json); [ "$c" = "200" ] && { echo OPENAPI_200; break; }; sleep 2; done
echo === WORKERS ===
ps aux | grep '[u]vicorn app.main' | wc -l
echo === NEW_ROUTES ===
curl -s http://localhost:8000/openapi.json | python3 -c "import sys,json; d=json.load(sys.stdin); ps=[p for p in d['paths'] if p.startswith('/v1/admin/gl') or p.startswith('/v1/admin/ar') or p.startswith('/v1/admin/pricing-rules')]; print(len(ps),'erp routes'); print(chr(10).join(sorted(ps)))"
